use std::fs
use std::strings

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut key: Vec<int> = []
    let mut lc: Vec<int> = []
    let mut rc: Vec<int> = []
    let mut root: int = -1
    for line in text.lines() {
        let parts: Vec<string> = strings::split_whitespace(line)
        if parts.len() == 0 { continue }
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse().unwrap_or(0)
            if root == -1 {
                key.push(x)
                lc.push(-1)
                rc.push(-1)
                root = 0
                println("ok")
            } else {
                let mut cur: int = root
                let mut done = false
                while !done {
                    let k = key[cur as usize]
                    if x == k {
                        println("dup")
                        done = true
                    } else if x < k {
                        if lc[cur as usize] == -1 {
                            let n: int = key.len() as int
                            key.push(x)
                            lc.push(-1)
                            rc.push(-1)
                            lc[cur as usize] = n
                            println("ok")
                            done = true
                        } else {
                            cur = lc[cur as usize]
                        }
                    } else {
                        if rc[cur as usize] == -1 {
                            let n: int = key.len() as int
                            key.push(x)
                            lc.push(-1)
                            rc.push(-1)
                            rc[cur as usize] = n
                            println("ok")
                            done = true
                        } else {
                            cur = rc[cur as usize]
                        }
                    }
                }
            }
        } else if cmd == "contains" {
            let x: int = parts[1].parse().unwrap_or(0)
            let mut cur: int = root
            let mut found = false
            while cur != -1 && !found {
                let k = key[cur as usize]
                if x == k {
                    found = true
                } else if x < k {
                    cur = lc[cur as usize]
                } else {
                    cur = rc[cur as usize]
                }
            }
            if found { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse().unwrap_or(0)
            let mut cur: int = root
            let mut par: int = -1
            let mut isleft = false
            let mut found = false
            while cur != -1 && !found {
                let k = key[cur as usize]
                if x == k {
                    found = true
                } else if x < k {
                    par = cur
                    isleft = true
                    cur = lc[cur as usize]
                } else {
                    par = cur
                    isleft = false
                    cur = rc[cur as usize]
                }
            }
            if !found {
                println("missing")
            } else {
                let a = lc[cur as usize]
                let b = rc[cur as usize]
                if a != -1 && b != -1 {
                    let mut s: int = b
                    let mut sp: int = cur
                    while lc[s as usize] != -1 {
                        sp = s
                        s = lc[s as usize]
                    }
                    key[cur as usize] = key[s as usize]
                    let child = rc[s as usize]
                    if sp == cur {
                        rc[cur as usize] = child
                    } else {
                        lc[sp as usize] = child
                    }
                } else {
                    let child = if a != -1 { a } else { b }
                    if par == -1 {
                        root = child
                    } else if isleft {
                        lc[par as usize] = child
                    } else {
                        rc[par as usize] = child
                    }
                }
                println("ok")
            }
        } else if cmd == "inorder" {
            let mut out: Vec<string> = []
            let mut stack: Vec<int> = []
            let mut cur: int = root
            while cur != -1 || stack.len() > 0 {
                while cur != -1 {
                    stack.push(cur)
                    cur = lc[cur as usize]
                }
                let n = stack.pop().unwrap_or(0)
                out.push("${key[n as usize]}")
                cur = rc[n as usize]
            }
            if out.len() == 0 { println("<empty>") } else { println(out.join(" ")) }
        } else if cmd == "height" {
            let mut best: int = 0
            if root != -1 {
                let mut ns: Vec<int> = [root]
                let mut ds: Vec<int> = [1]
                while ns.len() > 0 {
                    let n = ns.pop().unwrap_or(0)
                    let d = ds.pop().unwrap_or(0)
                    if d > best { best = d }
                    if lc[n as usize] != -1 {
                        ns.push(lc[n as usize])
                        ds.push(d + 1)
                    }
                    if rc[n as usize] != -1 {
                        ns.push(rc[n as usize])
                        ds.push(d + 1)
                    }
                }
            }
            println("${best}")
        } else if cmd == "min" || cmd == "max" {
            if root == -1 {
                println("empty")
            } else {
                let mut cur: int = root
                if cmd == "min" {
                    while lc[cur as usize] != -1 { cur = lc[cur as usize] }
                } else {
                    while rc[cur as usize] != -1 { cur = rc[cur as usize] }
                }
                println("${key[cur as usize]}")
            }
        }
    }
}

